def csv_line(cells):
    def q(c):
        return '"' + c.replace('"', '""') + '"' if any(ch in c for ch in ',"\n') else c
    return ','.join(q(c) for c in cells)


def main():
    with open(os.path.join(HERE, 'alipay_gbk.csv'), 'wb') as f:
        f.write('\r\n'.join(ALIPAY_HEAD + ALIPAY_ROWS + ALIPAY_TAIL + ['']).encode('gbk'))

    width = len(WECHAT_HEAD[-1])
    lines = [csv_line(r + [''] * (width - len(r))) if len(r) < width else csv_line(r) for r in WECHAT_HEAD]
    lines += [csv_line(r) for r in WECHAT_ROWS]
    with open(os.path.join(HERE, 'wechat.csv'), 'wb') as f:
        f.write(b'\xef\xbb\xbf' + '\n'.join(lines + ['']).encode('utf-8'))

    # 表格版的交易时间存成真正的日期单元格（Excel 序列号），检验按列语义换算。
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = '微信支付账单明细'
    for r in WECHAT_HEAD:
        ws.append(r)
    for r in WECHAT_ROWS:
        when = datetime.datetime.strptime(r[0], '%Y-%m-%d %H:%M:%S')
        ws.append([when] + [c.rstrip('\t') for c in r[1:]])
        ws.cell(row=ws.max_row, column=1).number_format = 'yyyy-mm-dd hh:mm:ss'
    wb.save(os.path.join(HERE, 'wechat.xlsx'))


if __name__ == '__main__':
    main()
